from lib import *
PAGE = page('trust-privacy',
 ("Privacy policy", "Politique de confidentialité", "سياسة الخصوصية"),
 ("What W5D collects, why, on what legal basis, who receives it, how long it is kept and how to exercise your rights, under Tunisian and international rules.",
  "Ce que W5D recueille, pourquoi, sur quelle base juridique, qui le reçoit, combien de temps il est conservé et comment exercer vos droits, selon les règles tunisiennes et internationales.",
  "ما تجمعه W5D ولماذا وعلى أي أساس قانوني ومن يتلقاه ومدة الاحتفاظ به وكيفية ممارسة حقوقك، وفق القواعد التونسية والدولية."),
 [
 hero('pv-hero', ("Privacy, **in plain terms.**", "La confidentialité, **en termes clairs.**", "الخصوصية، **بعبارات واضحة.**"),
  ("We collect what a form asks for, and nothing else. No data is sold, no advertising profile is built, and optional tracking stays off until you agree.",
   "Nous collectons les données demandées dans un formulaire, et rien de plus. Aucune donnée n’est vendue, aucun profil publicitaire n’est constitué, et le suivi facultatif reste désactivé tant que vous n’avez pas donné votre accord.",
   "نجمع ما يطلبه النموذج ولا شيء سواه. لا نبيع البيانات ولا نبني ملفًا إعلانيًا، ويبقى التتبع الاختياري معطّلًا حتى توافق عليه."),
  ("Privacy", "Confidentialité", "الخصوصية"),
  [(("Exercise your rights", "Exercer vos droits", "مارس حقوقك"), '/trust/data-rights/', 'peak', True)]),
 prose('pv-who', ("Who is responsible for your data", "Qui est responsable de vos données", "من المسؤول عن بياناتك"), [
  ("The data controller is {{ company.brand }}, a Tunisian initiative operated from {{ company.country }}. Its present legal form is shown in the footer of every page and on the [imprint](/trust/imprint/); we do not state a registration number here until the owner has one to show, and we do not invent one. For any question about personal data, write to {{ company.privacy_contact }}. A person reads that mailbox, during {{ company.hours }}, and answers within {{ company.response_days }} working days.",
   "Le responsable du traitement est {{ company.brand }}, une initiative tunisienne exploitée depuis la {{ company.country }}. Sa forme juridique actuelle figure dans le pied de page de chaque page et sur les [mentions légales](/trust/imprint/) ; nous n’indiquons pas de numéro d’immatriculation ici tant que le propriétaire n’en possède pas, et nous n’en inventons pas. Pour toute question relative aux données personnelles, écrivez à {{ company.privacy_contact }}. Une personne lit cette boîte, pendant {{ company.hours }}, et répond sous {{ company.response_days }} jours ouvrés.",
   "المسؤول عن المعالجة هو {{ company.brand }}، مبادرة تونسية تُدار من {{ company.country }}. وتظهر صيغتها القانونية الحالية في أسفل كل صفحة وفي [الإشعار القانوني](/trust/imprint/)؛ ولا نذكر هنا رقم تسجيل ما دام المالك لا يملك رقمًا يعرضه، ولا نختلق رقمًا. لأي سؤال عن المعطيات الشخصية راسلنا على {{ company.privacy_contact }}. يقرأ شخص هذا البريد خلال {{ company.hours }} ويجيب خلال {{ company.response_days }} أيام عمل."),
  ("This policy describes the public site, the accounts you can open on it, the forms, the certification and QCM rounds, the investor checkout, the referral programme and the sponsorship form. It does not cover other websites that you reach through a link, nor the payment providers once you are on their pages: each has its own policy, which you should read.",
   "La présente politique décrit le site public, les comptes que vous pouvez y ouvrir, les formulaires, les parcours de certification et de QCM, le paiement des investisseurs, le programme de parrainage et le formulaire de parrainage financier. Elle ne couvre pas les autres sites auxquels vous accédez par un lien, ni les prestataires de paiement une fois sur leurs pages : chacun a sa propre politique, que vous devriez lire.",
   "تصف هذه السياسة الموقع العام والحسابات التي يمكنك فتحها فيه والنماذج ومسارات الشهادات والاختبارات وخروج المستثمرين للدفع وبرنامج الإحالة ونموذج الرعاية. ولا تشمل المواقع الأخرى التي تصل إليها عبر رابط، ولا مزوّدي الدفع حين تصبح في صفحاتهم: لكل منهم سياسته التي ينبغي أن تقرأها.")]),
 table('pv-data', ("What we collect, why, and on what basis", "Ce que nous collectons, pourquoi, et sur quelle base", "ما نجمعه ولماذا وعلى أي أساس"),
  [("Data", "Données", "المعطيات"), ("Why", "Pourquoi", "السبب"), ("Basis", "Base", "الأساس"), ("Kept for", "Conservé", "مدة الحفظ")],
  [[("Account: name, e-mail, password (stored only as an Argon2id hash), language", "Compte : nom, e-mail, mot de passe (conservé seulement sous forme de hachage Argon2id), langue", "الحساب: الاسم والبريد وكلمة المرور (تُخزَّن فقط ببصمة Argon2id) واللغة"), ("To let you sign in, verify your address and recover your account", "Pour vous permettre de vous connecter, de vérifier votre adresse et de récupérer votre compte", "لتمكينك من الدخول والتحقق من بريدك واستعادة حسابك"), ("Contract", "Contrat", "العقد"), ("{{ privacy.retention_account_days }} days after you close the account", "{{ privacy.retention_account_days }} jours après la fermeture du compte", "{{ privacy.retention_account_days }} يومًا بعد إغلاق الحساب")],
   [("Messages you send through the contact form, with the desk and your address", "Messages envoyés par le formulaire de contact, avec le service choisi et votre adresse", "الرسائل المرسلة عبر نموذج الاتصال مع المكتب المختار وعنوانك"), ("To answer you and keep a record of what was said", "Pour vous répondre et conserver une trace de ce qui a été dit", "للرد عليك وحفظ سجل بما قيل"), ("Legitimate interest", "Intérêt légitime", "المصلحة المشروعة"), ("{{ privacy.retention_messages_months }} months", "{{ privacy.retention_messages_months }} mois", "{{ privacy.retention_messages_months }} شهرًا")],
   [("Applications and registrations: diploma, field, region, answers you give", "Candidatures et inscriptions : diplôme, domaine, région, réponses fournies", "طلبات التقديم والتسجيل: الشهادة والمجال والجهة والإجابات المقدَّمة"), ("To assess eligibility and place you on a certification path", "Pour évaluer l’éligibilité et vous placer sur un parcours de certification", "لتقييم الأهلية ووضعك على مسار اعتماد"), ("Your request", "Votre demande", "طلبك"), ("While the application is active, then {{ privacy.retention_account_days }} days", "Tant que la candidature est active, puis {{ privacy.retention_account_days }} jours", "ما دام الطلب فعّالًا ثم {{ privacy.retention_account_days }} يومًا")],
   [("QCM attempts, scores and certificates", "Tentatives de QCM, scores et certificats", "محاولات الاختبار ونتائجها والشهادات"), ("To score you, issue a verifiable certificate and let others check it", "Pour vous noter, délivrer un certificat vérifiable et permettre à des tiers de le vérifier", "لتقييمك وإصدار شهادة يمكن التحقق منها وإتاحة التحقق للغير"), ("Contract", "Contrat", "العقد"), ("For the life of the certificate ({{ cert.validity_months }} months) and the account", "Pendant la durée du certificat ({{ cert.validity_months }} mois) et du compte", "طيلة مدة الشهادة ({{ cert.validity_months }} شهرًا) والحساب")],
   [("Orders, pledges, subscriptions and payment references (never your card or wallet secrets)", "Commandes, engagements, abonnements et références de paiement (jamais vos secrets de carte ou de portefeuille)", "الطلبات والتعهدات والاشتراكات ومراجع الدفع (لا أسرار بطاقتك أو محفظتك أبدًا)"), ("To record what you paid for and to meet accounting duties", "Pour enregistrer ce que vous avez payé et remplir les obligations comptables", "لتسجيل ما دفعته والوفاء بالالتزامات المحاسبية"), ("Contract and legal duty", "Contrat et obligation légale", "العقد والالتزام القانوني"), ("{{ privacy.retention_accounting_years }} years (accounting-record retention)", "{{ privacy.retention_accounting_years }} ans (conservation des pièces comptables)", "{{ privacy.retention_accounting_years }} سنوات (حفظ الوثائق المحاسبية)")],
   [("Referral clicks: a hashed marker, never your name or address", "Clics de parrainage : un marqueur haché, jamais votre nom ni votre adresse", "نقرات الإحالة: علامة مشفّرة لا اسمك ولا عنوانك"), ("To credit a verified payment to the person who referred you", "Pour créditer un paiement vérifié à la personne qui vous a parrainé", "لاحتساب دفع تم التحقق منه لمن أحالك"), ("Your action (following a link)", "Votre action (suivre un lien)", "فعلك (اتباع رابط)"), ("{{ privacy.retention_affiliate_months }} months", "{{ privacy.retention_affiliate_months }} mois", "{{ privacy.retention_affiliate_months }} شهرًا")],
   [("Web-server logs: IP address, time, page, browser type", "Journaux du serveur web : adresse IP, heure, page, type de navigateur", "سجلات الخادم: عنوان IP والوقت والصفحة ونوع المتصفح"), ("To keep the site secure, stop abuse and fix faults", "Pour sécuriser le site, empêcher les abus et corriger les pannes", "لحماية الموقع ومنع الإساءة وإصلاح الأعطال"), ("Legitimate interest", "Intérêt légitime", "المصلحة المشروعة"), ("{{ privacy.retention_logs_days }} days", "{{ privacy.retention_logs_days }} jours", "{{ privacy.retention_logs_days }} يومًا")]],
  note=("We do not ask for national identity numbers, health data, religion, politics or any other sensitive category. If you write such information in a free-text field, tell us and we will remove it.",
        "Nous ne demandons ni numéro d’identité nationale, ni données de santé, ni religion, ni opinions politiques, ni aucune autre catégorie sensible. Si vous saisissez de telles informations dans un champ libre, dites-le-nous et nous les supprimerons.",
        "لا نطلب أرقام الهوية الوطنية ولا بيانات صحية ولا دينًا ولا آراء سياسية ولا أي فئة حساسة أخرى. وإذا كتبت معلومات كهذه في حقل نصي حر فأخبرنا وسنزيلها.")),
 prose('pv-sharing', ("Who receives your data", "Qui reçoit vos données", "من يتلقى بياناتك"), [
  ("We do not sell personal data and we do not rent it. Data is shared only with providers that perform a task we cannot do ourselves, and only what that task needs. Payment providers (D17, bank transfer instructions, and the online gateways Flouci, Konnect and Paymee when they are enabled) receive the amount, the order reference and the details needed to complete a payment. The mail service that carries our messages receives your address and the text of the message. The hosting provider stores the encrypted-in-transit data on our behalf.",
   "Nous ne vendons ni ne louons de données personnelles. Les données ne sont partagées qu’avec des prestataires qui accomplissent une tâche que nous ne pouvons pas réaliser nous-mêmes, et seulement ce que cette tâche exige. Les prestataires de paiement (D17, instructions de virement bancaire, et les passerelles en ligne Flouci, Konnect et Paymee lorsqu’elles sont activées) reçoivent le montant, la référence de commande et les informations nécessaires pour mener à bien un paiement. Le service de messagerie qui achemine nos messages reçoit votre adresse et le texte du message. L’hébergeur stocke pour notre compte les données chiffrées en transit.",
   "لا نبيع المعطيات الشخصية ولا نؤجّرها. ولا نشاركها إلا مع مزوّدين ينجزون مهمة لا نستطيع إنجازها بأنفسنا، وبقدر ما تحتاجه المهمة فقط. فمزوّدو الدفع (D17 وتعليمات التحويل البنكي، وبوابات Flouci وKonnect وPaymee عند تفعيلها) يتلقون المبلغ ومرجع الطلب والمعلومات اللازمة لإتمام الدفع. وخدمة البريد التي تنقل رسائلنا تتلقى عنوانك ونص الرسالة. ويخزّن المستضيف البيانات المشفّرة أثناء النقل نيابة عنا."),
  ("Where the owner switches them on, Google (Analytics, Tag Manager, Ads, reCAPTCHA) and Meta (Pixel) receive technical visit data under the conditions described in the [cookie policy](/trust/cookies/). Advertising partners are never given your account data. We may disclose data to a court, a regulator or the police when a Tunisian or applicable foreign law compels us, and we will say so when the law allows us to. If the business is ever transferred, we will tell you before your data moves and you will be able to object or delete your account.",
   "Lorsque le propriétaire les active, Google (Analytics, Tag Manager, Ads, reCAPTCHA) et Meta (Pixel) reçoivent des données techniques de visite dans les conditions décrites dans la [politique relative aux cookies](/trust/cookies/). Les partenaires publicitaires ne reçoivent jamais les données de votre compte. Nous pouvons communiquer des données à un tribunal, à une autorité de contrôle ou à la police lorsqu’une loi tunisienne ou étrangère applicable nous y oblige, et nous vous en informerons quand la loi le permet. Si l’activité devait un jour être cédée, nous vous préviendrions avant le transfert de vos données et vous pourriez vous y opposer ou supprimer votre compte.",
   "وعندما يفعّلها المالك، تتلقى Google (التحليلات ومدير العلامات والإعلانات وreCAPTCHA) وMeta (البكسل) بيانات زيارة تقنية وفق الشروط الواردة في [سياسة الملفات](/trust/cookies/). ولا يحصل الشركاء الإعلانيون على بيانات حسابك أبدًا. وقد نفصح عن معطيات لمحكمة أو جهة رقابية أو الشرطة حين يُلزمنا بذلك قانون تونسي أو أجنبي واجب التطبيق، وسنخبرك بذلك متى سمح القانون. وإذا نُقل النشاط يومًا فسنُعلمك قبل انتقال بياناتك ويمكنك الاعتراض أو حذف حسابك.")]),
 prose('pv-transfer', ("Transfers outside Tunisia", "Transferts hors de Tunisie", "النقل خارج تونس"), [
  ("Some providers process data outside Tunisia, for example in the European Union or the United States. Organic Law 2004-63 restricts transfers of personal data abroad and gives the national authority (INPDP) a role in authorising them in some cases; the GDPR sets its own conditions for transfers out of the European Economic Area. We choose providers that document their safeguards, we send them the minimum, and we ask our Tunisian lawyer to confirm which authorisations or contractual clauses are required before any new transfer starts.",
   "Certains prestataires traitent des données hors de Tunisie, par exemple dans l’Union européenne ou aux États-Unis. La loi organique 2004-63 encadre les transferts de données personnelles vers l’étranger et confie à l’autorité nationale (INPDP) un rôle d’autorisation dans certains cas ; le RGPD fixe ses propres conditions pour les transferts hors de l’Espace économique européen. Nous choisissons des prestataires qui documentent leurs garanties, nous leur transmettons le minimum, et nous demandons à notre avocat tunisien de confirmer quelles autorisations ou clauses contractuelles sont requises avant tout nouveau transfert.",
   "يعالج بعض المزوّدين البيانات خارج تونس، مثل الاتحاد الأوروبي أو الولايات المتحدة. ويقيّد القانون الأساسي عدد 2004-63 نقل المعطيات الشخصية إلى الخارج ويمنح الهيئة الوطنية (INPDP) دورًا في الترخيص بذلك في بعض الحالات؛ وللائحة الأوروبية شروطها الخاصة بالنقل خارج المجال الاقتصادي الأوروبي. ونختار مزوّدين يوثّقون ضماناتهم، ونرسل لهم الحد الأدنى، ونطلب من محامينا التونسي تأكيد التراخيص أو البنود التعاقدية المطلوبة قبل بدء أي نقل جديد.")]),
 defs('pv-key', ("Your data, in short", "Vos données, en bref", "بياناتك باختصار"), [
  (("What we keep", "Ce que nous conservons", "ما نحتفظ به"), ("Your account, your pledges and applications, your QCM attempts and certificates, and the messages you send us.", "Votre compte, vos engagements et candidatures, vos tentatives QCM et certificats, et les messages que vous nous envoyez.", "حسابك وتعهداتك وطلباتك ومحاولات الاختبار وشهاداتك والرسائل التي ترسلها إلينا.")),
  (("What we never keep", "Ce que nous ne conservons jamais", "ما لا نحتفظ به أبدًا"), ("Card numbers, wallet secrets, your password in readable form, or any sensitive category of data.", "Numéros de carte, secrets de portefeuille, votre mot de passe en clair, ou toute catégorie sensible de données.", "أرقام البطاقات وأسرار المحافظ وكلمة مرورك بصيغة مقروءة أو أي فئة حساسة من المعطيات.")),
  (("What we never do", "Ce que nous ne faisons jamais", "ما لا نفعله أبدًا"), ("Sell data, build advertising profiles, or load third-party trackers before you agree.", "Vendre des données, constituer des profils publicitaires ou charger des traceurs tiers avant votre accord.", "بيع البيانات أو بناء ملفات إعلانية أو تحميل متتبعات طرف ثالث قبل موافقتك.")),
  (("Who decides", "Qui décide", "من يقرر"), ("You. You can see, correct, export or delete your data, and refuse optional tracking at any time.", "Vous. Vous pouvez consulter, corriger, exporter ou supprimer vos données et refuser le suivi facultatif à tout moment.", "أنت. يمكنك الاطلاع على بياناتك وتصحيحها وتصديرها وحذفها ورفض التتبع الاختياري في أي وقت.")),
 ]),
 prose('pv-security', ("How we protect it", "Comment nous la protégeons", "كيف نحميها"), [
  ("Passwords are stored only as Argon2id hashes. Every state-changing form carries a CSRF token, sessions are HttpOnly and SameSite, and the site is served over HTTPS in production. Scripts load only from our own domain under a strict Content-Security-Policy, which also limits what an injected script could reach. Access to the owner portal is role-based and every sensitive action is written to an audit log. The full list of controls is on the [security page](/trust/security/).",
   "Les mots de passe ne sont conservés que sous forme de hachages Argon2id. Chaque formulaire qui modifie un état porte un jeton CSRF, les sessions sont HttpOnly et SameSite, et le site est servi en HTTPS en production. Les scripts ne se chargent que depuis notre propre domaine sous une politique de sécurité du contenu stricte, qui limite aussi ce qu’un script injecté pourrait atteindre. L’accès au portail du propriétaire est fondé sur les rôles et chaque action sensible est inscrite dans un journal d’audit. La liste complète des contrôles figure sur la [page sécurité](/trust/security/).",
   "لا تُخزَّن كلمات المرور إلا ببصمات Argon2id. وكل نموذج يغيّر حالة يحمل رمز CSRF، والجلسات HttpOnly وSameSite، ويُقدَّم الموقع عبر HTTPS في الإنتاج. ولا تُحمَّل النصوص البرمجية إلا من نطاقنا وفق سياسة أمان محتوى صارمة تحدّ أيضًا مما قد يصل إليه نص مُحقَن. والوصول إلى بوابة المالك قائم على الأدوار وكل إجراء حساس يُسجَّل في سجل تدقيق. وقائمة الضوابط الكاملة في [صفحة الأمان](/trust/security/)."),
  ("If a breach puts your personal data at risk, we will tell the people affected without undue delay and notify the competent authority within {{ legal.ack_hours }} hours of becoming aware where the law requires it, saying what happened, what data was involved and what you can do. No system is perfectly secure, and we do not claim that ours is; we claim that we try, that we log, and that we tell you.",
   "Si une violation met vos données personnelles en danger, nous informerons les personnes concernées sans retard injustifié et nous notifierons l’autorité compétente dans les {{ legal.ack_hours }} heures suivant la prise de connaissance lorsque la loi l’exige, en indiquant ce qui s’est passé, quelles données sont concernées et ce que vous pouvez faire. Aucun système n’est parfaitement sûr, et nous ne prétendons pas que le nôtre le soit ; nous affirmons que nous essayons, que nous journalisons et que nous vous le disons.",
   "إذا عرّض اختراق بياناتك الشخصية للخطر فسنُعلم المعنيين دون تأخير غير مبرر ونُخطر الجهة المختصة خلال {{ legal.ack_hours }} ساعة من علمنا حيث يشترط القانون، مبيّنين ما حدث والبيانات المعنية وما يمكنك فعله. ولا يوجد نظام آمن تمامًا ولا ندّعي ذلك لنظامنا؛ ما ندّعيه أننا نحاول ونسجّل ونخبرك.")]),
 prose('pv-special', ("Children, automation and your rights in short", "Enfants, automatisation et résumé de vos droits", "القاصرون والأتمتة وخلاصة حقوقك"), [
  ("The site is not directed at children, and applicants must be adults able to enter a contract under Tunisian law. If you believe a child has given us data, write to us and we will delete it. Scoring of QCM rounds is automatic, but the rules are published, a result can be challenged by writing to us, and a person looks at every contested case; no decision with legal effect on you is taken by a machine alone.",
   "Le site ne s’adresse pas aux enfants, et les candidats doivent être majeurs et capables de contracter selon le droit tunisien. Si vous pensez qu’un enfant nous a communiqué des données, écrivez-nous et nous les supprimerons. La notation des QCM est automatique, mais les règles sont publiées, un résultat peut être contesté en nous écrivant, et une personne examine chaque cas contesté ; aucune décision produisant des effets juridiques à votre égard n’est prise par une machine seule.",
   "الموقع غير موجَّه إلى الأطفال، ويجب أن يكون المتقدمون راشدين قادرين على التعاقد وفق القانون التونسي. وإذا ظننت أن طفلًا زوّدنا ببيانات فراسلنا وسنحذفها. وتصحيح الاختبارات آلي، لكن القواعد منشورة ويمكن الطعن في النتيجة بمراسلتنا، ويراجع شخص كل حالة متنازع عليها؛ ولا يُتخذ أي قرار ذي أثر قانوني عليك بواسطة آلة وحدها."),
  ("You may ask to see your data, correct it, delete it, restrict or object to its use, receive a copy in a common format, withdraw consent, and complain to a regulator. The steps, the answer deadlines and the limits (for example, accounting records we must legally keep) are on the page [your data rights](/trust/data-rights/). Complaints can be addressed to the Tunisian authority (INPDP) or, if you live in the European Union, to your national supervisory authority; we would still like the chance to put it right first.",
   "Vous pouvez demander à consulter vos données, à les corriger, à les supprimer, à en restreindre l’usage ou à vous y opposer, à en recevoir une copie dans un format courant, à retirer votre consentement et à saisir une autorité de contrôle. Les démarches, les délais de réponse et les limites (par exemple les pièces comptables que nous devons légalement conserver) figurent sur la page [vos droits sur vos données](/trust/data-rights/). Vous pouvez adresser une plainte à l’autorité tunisienne (INPDP) ou, si vous résidez dans l’Union européenne, à votre autorité de contrôle nationale ; nous aimerions toutefois avoir d’abord la possibilité de corriger la situation.",
   "يمكنك طلب الاطلاع على بياناتك وتصحيحها وحذفها وتقييد استعمالها أو الاعتراض عليه والحصول على نسخة بصيغة شائعة وسحب موافقتك والشكوى إلى جهة رقابية. والخطوات وآجال الرد والحدود (مثل الوثائق المحاسبية التي يلزمنا القانون بحفظها) في صفحة [حقوقك في بياناتك](/trust/data-rights/). ويمكن توجيه الشكوى إلى السلطة التونسية (INPDP) أو إلى سلطتك الوطنية إن كنت مقيمًا في الاتحاد الأوروبي؛ غير أننا نرجو أن تتيح لنا فرصة التصحيح أولًا.")]),
 faq('pv-faq', ("Privacy, asked plainly", "La confidentialité, en questions simples", "أسئلة بسيطة عن الخصوصية"), [
  (("Is my data used to show me advertising?", "Mes données servent-elles à m’afficher de la publicité ?", "هل تُستخدم بياناتي لعرض إعلانات علي؟"), ("No. Your account data is never given to advertisers. If advertising is ever shown, it appears only on a few public reading pages, never on your account, checkout or certificate pages; see the [advertising policy](/trust/ads-policy/).", "Non. Les données de votre compte ne sont jamais transmises aux annonceurs. Si de la publicité est un jour affichée, elle n’apparaît que sur quelques pages publiques de lecture, jamais sur votre compte, le paiement ou vos certificats ; voir la [politique publicitaire](/trust/ads-policy/).", "لا. لا تُمنح بيانات حسابك للمعلنين أبدًا. وإن ظهر إعلان يومًا فسيكون في بعض صفحات القراءة العامة فقط، لا في حسابك ولا في الدفع ولا في الشهادات؛ انظر [سياسة الإعلانات](/trust/ads-policy/).")),
  (("Can I delete my account?", "Puis-je supprimer mon compte ?", "هل يمكنني حذف حسابي؟"), ("Yes. Write to {{ company.privacy_contact }} from the address on the account. It is erased {{ privacy.retention_account_days }} days later, except records the law obliges us to keep.", "Oui. Écrivez à {{ company.privacy_contact }} depuis l’adresse du compte. Il est effacé {{ privacy.retention_account_days }} jours plus tard, sauf les pièces que la loi nous oblige à conserver.", "نعم. راسل {{ company.privacy_contact }} من العنوان المسجَّل في الحساب. يُمحى بعد {{ privacy.retention_account_days }} يومًا، باستثناء الوثائق التي يلزمنا القانون بحفظها.")),
  (("Is my certificate public?", "Mon certificat est-il public ?", "هل شهادتي علنية؟"), ("Only the certificate number lookup is public: anyone with the number can confirm that it exists, its level, and its dates. Your other data is not shown.", "Seule la recherche par numéro de certificat est publique : toute personne disposant du numéro peut confirmer son existence, son niveau et ses dates. Vos autres données ne sont pas affichées.", "التحقق برقم الشهادة وحده علني: يمكن لمن لديه الرقم أن يتأكد من وجودها ومستواها وتواريخها. ولا تُعرض بياناتك الأخرى.")),
  (("How often is this policy updated?", "À quelle fréquence cette politique est-elle mise à jour ?", "كم مرة تُحدَّث هذه السياسة؟"), ("It is reviewed at least every {{ legal.review_months }} months and whenever a feature changes what we collect. The date of the last review is on every trust page.", "Elle est revue au moins tous les {{ legal.review_months }} mois et chaque fois qu’une fonctionnalité modifie ce que nous collectons. La date de la dernière revue figure sur chaque page de confiance.", "تُراجَع مرة كل {{ legal.review_months }} أشهر على الأقل وكلما غيّرت ميزة ما نجمعه. وتاريخ آخر مراجعة على كل صفحة ثقة.")),
 ]),
 prose('pv-related', ("Related pages and review", "Pages liées et revue", "صفحات ذات صلة والمراجعة"), [
  ("See also the [cookie policy](/trust/cookies/), [your data rights](/trust/data-rights/), the [terms](/trust/terms/), the [refund policy](/trust/refunds/), the [security page](/trust/security/) and the [corrections form](/trust/corrections/). To report an error in this policy, write to {{ company.privacy_contact }}.",
   "Voir aussi la [politique relative aux cookies](/trust/cookies/), [vos droits sur vos données](/trust/data-rights/), les [conditions](/trust/terms/), la [politique de remboursement](/trust/refunds/), la [page sécurité](/trust/security/) et le [formulaire de corrections](/trust/corrections/). Pour signaler une erreur dans cette politique, écrivez à {{ company.privacy_contact }}.",
   "انظر أيضًا [سياسة الملفات](/trust/cookies/) و[حقوقك في بياناتك](/trust/data-rights/) و[الشروط](/trust/terms/) و[سياسة الاسترداد](/trust/refunds/) و[صفحة الأمان](/trust/security/) و[نموذج التصحيحات](/trust/corrections/). وللإبلاغ عن خطأ في هذه السياسة راسل {{ company.privacy_contact }}."),
  VERIFY]),
 cta_block('pv-final', ("Questions about your data? **Ask a person.**", "Une question sur vos données ? **Posez-la à une personne.**", "سؤال عن بياناتك؟ **اسأل شخصًا.**"), ("Every request about personal data is read by a human and answered in writing.", "Chaque demande relative aux données personnelles est lue par un humain et reçoit une réponse écrite.", "يقرأ إنسان كل طلب يتعلق بالمعطيات الشخصية ويُجاب عنه كتابةً."),
  [(("Your data rights", "Vos droits", "حقوقك"), '/trust/data-rights/', 'peak', True), (("Cookie settings and policy", "Cookies : paramètres et politique", "الملفات: الإعدادات والسياسة"), '/trust/cookies/', 'ghost', False)]),
 ])
